      "path": "packages/dsh-verify-isolated/skills/dsh-verify-isolated/scripts/browser-driver.mjs",
      "content": "#!/usr/bin/env node\n/**\n * browser-driver.mjs — dsh-verify-isolated 自带独立浏览器实例驱动（raw CDP，零依赖）。\n *\n * 设计目标：每个验证任务持有独立 chromium 实例（独立 user-data-dir + 独立调试端口），\n * 多会话并行互不可见，从结构上杜绝共享 MCP server 的 tab 漂移/串扰。零第三方依赖，\n * 只使用 Node 内置模块（child_process / fs / path / os / net / http 与 Node>=22 的\n * 全局 WebSocket），遵守发布物零运行时依赖纪律。\n *\n * 命令/参数契约以 `--help` 输出为准（launch / quit / snapshot / click / eval / fill /\n * wait / screenshot / console，统一 --json 输出）。内核探测链见 detectChrome()。\n *\n * 页面命令（snapshot / click / eval / fill / wait / screenshot / console）可携带设备\n * 模拟 flag（--width / --height / --dpr / --mobile）：命令内应用、结束前清除，命令\n * 之间互不影响——不做成粘性状态的原因见 lib/emulation.mjs 头部（CDP 会话语义）。\n *\n * 导航命令（snapshot / click / wait / screenshot / console）的 `--url` 接受保留值\n * `state`：改用 state 文件里 verify-isolated.mjs 写入的带令牌 URL（GUI 带鉴权，\n * 裸端口只得到 401）。省略 `--url` 仍是**不导航**——自动导航会抹掉上一条命令的\n * 页面状态，多步交互验证（点一下再读结果）就断了。\n *\n * 导航后自动跳过 dsh web 首启弹窗（--no-auto-dismiss 关闭）：内测声明与 API Key\n * 弹窗把应用根置为 inert，若不跳过，页面命令的点击全部静默失效；成因与预置策略见\n * lib/onboarding.mjs 头部。\n */\nimport { spawn } from \"node:child_process\";\nimport {\n  existsSync,\n  mkdtempSync,\n  readFileSync,\n  readdirSync,\n  rmSync,\n  statSync,\n  unlinkSync,\n  writeFileSync,\n} from \"node:fs\";\nimport { homedir, platform, tmpdir } from \"node:os\";\nimport { delimiter, join } from \"node:path\";\nimport { createServer } from \"node:net\";\nimport { get } from \"node:http\";\nimport { buildDeviceMetrics, parseEmulationFlags } from \"./lib/emulation.mjs\";\nimport { MAX_OVERLAY_ROUNDS, buildOverlayProbeExpression, redactToken } from \"./lib/onboarding.mjs\";\n\n// --- 基础工具 ---\n\nconst sleep = (ms) => new Promise((r) => setTimeout(r, ms));\n\n/** 首启弹窗等待窗口（弹窗异步挂载，探一次会漏检；见 settleOverlays）。 */\nconst OVERLAY_WAIT_MS = 1500;\n\nasync function poll(fn, timeoutMs, intervalMs = 200) {\n  const deadline = Date.now() + timeoutMs;\n  for (;;) {\n    if (await fn()) return true;\n    if (Date.now() >= deadline) return false;\n    await sleep(intervalMs);\n  }\n}\n\nfunction jsonOut(obj, pretty) {\n  process.stdout.write(JSON.stringify(obj, null, pretty ? 2 : 0) + \"\\n\");\n}\n\n// 实例级输出：统一 JSON，默认紧凑单行\nconst out = (flags, obj) => jsonOut(obj, flags.has(\"pretty\"));\n\nfunction fail(msg) {\n  jsonOut({ ok: false, error: msg });\n  process.exit(1);\n}\n\nfunction parseArgs(argv) {\n  const flags = new Map();\n  const positionals = [];\n  for (let i = 0; i < argv.length; i++) {\n    const a = argv[i];\n    if (a === \"--\") {\n      positionals.push(...argv.slice(i + 1));\n      break;\n    }\n    if (!a.startsWith(\"--\")) {\n      positionals.push(a);\n      continue;\n    }\n    const eq = a.indexOf(\"=\");\n    if (eq !== -1) {\n      flags.set(a.slice(2, eq), a.slice(eq + 1));\n      continue;\n    }\n    const key = a.slice(2);\n    const next = argv[i + 1];\n    if (next !== undefined && !next.startsWith(\"--\")) {\n      flags.set(key, next);\n      i++;\n    } else flags.set(key, \"true\");\n  }\n  return { flags, positionals };\n}\n\nfunction flag(flags, name, def) {\n  const v = flags.get(name);\n  return v === undefined ? def : v;\n}\n\nfunction httpJson(url, timeoutMs = 3000) {\n  return new Promise((resolve, reject) => {\n    const req = get(url, (res) => {\n      let body = \"\";\n      res.on(\"data\", (c) => {\n        body += c;\n      });\n      res.on(\"end\", () => {\n        try {\n          resolve(JSON.parse(body));\n        } catch (e) {\n          reject(new Error(`解析 ${url} 响应失败: ${e.message}`));\n        }\n      });\n    });\n    req.setTimeout(timeoutMs, () => req.destroy(new Error(`请求 ${url} 超时`)));\n    req.on(\"error\", reject);\n  });\n}\n\nfunction pidAlive(pid) {\n  if (!pid) return false;\n  try {\n    process.kill(pid, 0);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\nasync function waitPidExit(pid, timeoutMs) {\n  await poll(() => !pidAlive(pid), timeoutMs, 200);\n  return !pidAlive(pid);\n}\n\n// --- CDP WebSocket RPC（内置全局 WebSocket，Node >= 22） ---\n\nfunction rpc(wsUrl, method, params = {}, timeoutMs = 15000) {\n  return new Promise((resolve, reject) => {\n    if (typeof WebSocket !== \"function\") {\n      reject(\n        new Error(\n          \"当前 Node 无全局 WebSocket（需 Node >= 22），请升级 Node 或改用系统 Chrome 手工调试\",\n        ),\n      );\n      return;\n    }\n    const ws = new WebSocket(wsUrl);\n    const pending = new Map();\n    let nextId = 1;\n    const timer = setTimeout(() => {\n      cleanup();\n      reject(new Error(`CDP ${method} 超时（${timeoutMs}ms）`));\n    }, timeoutMs);\n    const cleanup = () => {\n      clearTimeout(timer);\n      try {\n        ws.close();\n      } catch {}\n    };\n    ws.onopen = () => {\n      ws.send(JSON.stringify({ id: nextId, method, params }));\n      pending.set(nextId, { resolve, reject });\n      nextId++;\n    };\n    ws.onmessage = (ev) => {\n      let msg;\n      try {\n        msg = JSON.parse(String(ev.data));\n      } catch {\n        return;\n      }\n      if (msg.id && pending.has(msg.id)) {\n        const p = pending.get(msg.id);\n        pending.delete(msg.id);\n        if (msg.error) {\n          cleanup();\n          p.reject(new Error(`${method}: ${msg.error.message}`));\n        } else {\n          cleanup();\n          p.resolve(msg.result);\n        }\n      }\n    };\n    ws.onerror = () => {\n      cleanup();\n      reject(new Error(`WebSocket 连接失败: ${wsUrl}`));\n    };\n    ws.onclose = () => {\n      cleanup();\n      reject(new Error(`WebSocket 已关闭: ${wsUrl}`));\n    };\n  });\n}\n\n// --- 浏览器内核探测（三平台，唯一收敛点） ---\n\nconst isFile = (p) => {\n  try {\n    return statSync(p).isFile();\n  } catch {\n    return false;\n  }\n};\n\nfunction* msPlaywrightCandidates() {\n  let dir = null;\n  if (platform() === \"win32\")\n    dir = process.env.LOCALAPPDATA ? join(process.env.LOCALAPPDATA, \"ms-playwright\") : null;\n  else if (platform() === \"darwin\") dir = join(homedir(), \"Library\", \"Caches\", \"ms-playwright\");\n  else dir = join(homedir(), \".cache\", \"ms-playwright\");\n  if (!dir || !existsSync(dir)) return;\n  for (const entry of readdirSync(dir)) {\n    const base = join(dir, entry);\n    let st;\n    try {\n      st = statSync(base);\n    } catch {\n      continue;\n    }\n    if (!st.isDirectory() || !entry.startsWith(\"chrom\")) continue;\n    // linux\n    for (const p of [\n      join(base, \"chrome-linux\", \"chrome\"),\n      join(base, \"chrome-headless-shell-linux64\", \"chrome-headless-shell\"),\n    ])\n      if (isFile(p)) yield p;\n    // mac：chrome-mac/Chromium.app/Contents/MacOS/Chromium 或其它 .app 名\n    if (platform() === \"darwin\") {\n      for (const sub of [\"chrome-mac\", \"chromium-mac\"]) {\n        const appDir = join(base, sub);\n        if (!existsSync(appDir)) continue;\n        for (const app of readdirSync(appDir)) {\n          const bin = join(appDir, app, \"Contents\", \"MacOS\", app.replace(/\\.app$/, \"\"));\n          if (isFile(bin)) yield bin;\n        }\n      }\n    }\n    // win\n    for (const p of [\n      join(base, \"chrome-win\", \"chrome.exe\"),\n      join(base, \"chrome-win32\", \"chrome.exe\"),\n      join(base, \"chrome-headless-shell-win64\", \"chrome-headless-shell.exe\"),\n    ])\n      if (isFile(p)) yield p;\n  }\n}\n\nfunction* pathCandidates() {\n  const names = [\n    \"google-chrome\",\n    \"google-chrome-stable\",\n    \"chromium\",\n    \"chromium-browser\",\n    \"chrome\",\n    \"msedge\",\n  ];\n  const paths = (process.env.PATH || \"\").split(delimiter).filter(Boolean);\n  for (const dir of paths) {\n    for (const name of names) {\n      const p = join(dir, name);\n      if (isFile(p)) yield p;\n      if (platform() === \"win32\") {\n        const pe = p + \".exe\";\n        if (isFile(pe)) yield pe;\n      }\n    }\n  }\n}\n\nfunction* commonPathCandidates() {\n  const home = homedir();\n  if (platform() === \"darwin\") {\n    const apps = [\"Google Chrome\", \"Chromium\", \"Microsoft Edge\", \"Brave Browser\"];\n    for (const root of [\"/Applications\", join(home, \"Applications\")]) {\n      for (const app of apps) {\n        const p = join(root, `${app}.app`, \"Contents\", \"MacOS\", app);\n        if (isFile(p)) yield p;\n      }\n    }\n  } else if (platform() === \"win32\") {\n    const roots = [\n      process.env.ProgramFiles,\n      process.env[\"ProgramFiles(x86)\"],\n      process.env.LOCALAPPDATA,\n    ].filter(Boolean);\n    const subs = [\n      join(\"Google\", \"Chrome\", \"Application\", \"chrome.exe\"),\n      join(\"Chromium\", \"Application\", \"chrome.exe\"),\n      join(\"Microsoft\", \"Edge\", \"Application\", \"msedge.exe\"),\n    ];\n    for (const root of roots)\n      for (const sub of subs) {\n        const p = join(root, sub);\n        if (isFile(p)) yield p;\n      }\n  } else {\n    for (const p of [\n      \"/usr/bin/google-chrome\",\n      \"/usr/bin/chromium\",\n      \"/usr/bin/chromium-browser\",\n      \"/usr/local/bin/google-chrome\",\n      \"/opt/google/chrome/chrome\",\n      \"/snap/bin/chromium\",\n      \"/usr/bin/microsoft-edge\",\n    ])\n      if (isFile(p)) yield p;\n  }\n}\n\nconst INSTALL_GUIDE = `未探测到 Chromium 系浏览器内核。可执行安装指引：\n  - Linux (Debian/Ubuntu): sudo apt-get install -y chromium-browser   或安装 google-chrome-stable（官网 .deb）\n  - Linux (Fedora):       sudo dnf install -y chromium\n  - macOS:                brew install --cask google-chrome   （或 chromium）\n  - Windows:              winget install Google.Chrome        （或 Microsoft.Edge）\n  - 任意平台：也可 npx playwright install chromium（默认装入 ~/.cache/ms-playwright 缓存，本驱动会自动发现）\n  已装但探测不到时，用 DSH_VERIFY_CHROME=/path/to/chrome（或 chromium/msedge）显式指定内核路径`;\n\nfunction detectChrome() {\n  const envOverride = process.env.DSH_VERIFY_CHROME;\n  if (envOverride) {\n    if (isFile(envOverride)) return envOverride;\n    fail(`DSH_VERIFY_CHROME 指定路径不存在: ${envOverride}\\n${INSTALL_GUIDE}`);\n  }\n  for (const cand of [\n    ...msPlaywrightCandidates(),\n    ...pathCandidates(),\n    ...commonPathCandidates(),\n  ]) {\n    if (isFile(cand)) return cand;\n  }\n  fail(INSTALL_GUIDE);\n}\n\n// --- launch / quit ---\n\nasync function findFreePort() {\n  return new Promise((resolve, reject) => {\n    const srv = createServer();\n    srv.on(\"error\", reject);\n    srv.listen(0, \"127.0.0.1\", () => {\n      const port = srv.address().port;\n      srv.close(() => resolve(port));\n    });\n  });\n}\n\nfunction readState(statePath) {\n  if (!existsSync(statePath)) fail(`state 文件不存在: ${statePath}（请先 launch）`);\n  try {\n    return JSON.parse(readFileSync(statePath, \"utf8\"));\n  } catch {\n    fail(`state 文件解析失败: ${statePath}`);\n  }\n}\n\nasync function cmdLaunch(flags) {\n  const statePath = flag(flags, \"state\", \"browser.state\");\n  const chromePath = flag(flags, \"chrome\", null);\n  const userDataDir = flag(flags, \"user-data-dir\", null);\n  const port = Number(flag(flags, \"port\", \"0\"));\n  const ownedDir = !userDataDir; // 未显式指定则 mkdtemp 自建，quit 时一并清理\n  const finalUserDataDir = userDataDir || mkdtempSync(join(tmpdir(), \"dsh-verify-\"));\n  const bin = chromePath || detectChrome();\n\n  let actualPort = port;\n  if (!actualPort) actualPort = await findFreePort();\n\n  const stderrBuf = [];\n  const headlessFlags = [\"--headless=new\", \"--headless\"];\n  let child = null;\n  let version = null;\n\n  for (const headless of headlessFlags) {\n    const args = [\n      headless,\n      \"--disable-gpu\",\n      \"--no-first-run\",\n      \"--no-default-browser-check\",\n      \"--disable-dev-shm-usage\",\n      \"--remote-debugging-address=127.0.0.1\",\n      `--remote-debugging-port=${actualPort}`,\n      `--user-data-dir=${finalUserDataDir}`,\n      \"about:blank\",\n    ];\n    stderrBuf.length = 0;\n    child = spawn(bin, args, { stdio: [\"ignore\", \"ignore\", \"pipe\"] });\n    child.unref(); // daemon：父进程退出不等待浏览器，实例由 state 文件管理\n    child.stderr.on(\"data\", (c) => {\n      if (stderrBuf.join(\"\").length < 4096) stderrBuf.push(String(c));\n    });\n    try {\n      version = await waitForDebugEndpoint(actualPort, child, 15000, () =>\n        stderrBuf.join(\"\").split(\"\\n\").slice(-8).join(\"\\n\"),\n      );\n      break;\n    } catch (e) {\n      if (child && pidAlive(child.pid)) {\n        try {\n          child.kill(\"SIGKILL\");\n        } catch {}\n      }\n      const headlessHint = /headless/i.test(stderrBuf.join(\"\"));\n      if (headless === \"--headless=new\" && headlessHint && child.exitCode !== null) continue; // 旧内核不认 =new，回退\n      throw e;\n    }\n  }\n\n  const state = {\n    version: 1,\n    pid: child.pid,\n    port: actualPort,\n    chromePath: bin,\n    userDataDir: finalUserDataDir,\n    userDataDirOwned: ownedDir,\n    wsUrl: version.webSocketDebuggerUrl,\n    launchedAt: new Date().toISOString(),\n  };\n  // 0o600：state 含调试 wsUrl/pid 等敏感信息，仅限本用户可读\n  writeFileSync(statePath, JSON.stringify(state, null, 2), { mode: 0o600 });\n  out(flags, { ok: true, ...state, stateFile: statePath });\n}\n\nasync function waitForDebugEndpoint(port, child, timeoutMs, stderrSnapshot) {\n  const deadline = Date.now() + timeoutMs;\n  let stderrTail = \"\";\n  for (;;) {\n    if (child.exitCode !== null) {\n      stderrTail = stderrSnapshot();\n      throw new Error(`浏览器进程提前退出（exit=${child.exitCode}）\\n${stderrTail}`);\n    }\n    try {\n      const v = await httpJson(`http://127.0.0.1:${port}/json/version`, 1000);\n      if (v && v.webSocketDebuggerUrl) return v;\n    } catch {}\n    if (Date.now() >= deadline)\n      throw new Error(`等待 CDP 就绪超时（${timeoutMs}ms）\\n${stderrTail}`);\n    await sleep(200);\n  }\n}\n\nasync function cmdQuit(flags) {\n  const statePath = flag(flags, \"state\", \"browser.state\");\n  const st = readState(statePath);\n  // 1. CDP 优雅关闭（浏览器自行释放 user-data-dir 锁）\n  try {\n    const v = await httpJson(`http://127.0.0.1:${st.port}/json/version`, 1500);\n    if (v && v.webSocketDebuggerUrl) await rpc(v.webSocketDebuggerUrl, \"Browser.close\", {}, 5000);\n  } catch {}\n  // 2. 等进程退出，兜底 SIGTERM / SIGKILL\n  if (st.pid && pidAlive(st.pid)) {\n    await waitPidExit(st.pid, 5000);\n    if (pidAlive(st.pid)) {\n      try {\n        process.kill(st.pid, \"SIGTERM\");\n      } catch {}\n      await waitPidExit(st.pid, 3000);\n      if (pidAlive(st.pid)) {\n        try {\n          process.kill(st.pid, \"SIGKILL\");\n        } catch {}\n      }\n    }\n  }\n  const exited = st.pid ? !pidAlive(st.pid) : true;\n  // 3. 清理自建临时目录与 state 文件\n  if (st.userDataDirOwned && st.userDataDir) {\n    try {\n      rmSync(st.userDataDir, { recursive: true, force: true });\n    } catch {}\n  }\n  try {\n    unlinkSync(statePath);\n  } catch {}\n  out(flags, {\n    ok: true,\n    pid: st.pid,\n    exited,\n    cleaned: st.userDataDirOwned ? st.userDataDir : null,\n    stateFile: statePath,\n  });\n}\n\n// --- 页面操作（每次调用独立连接，操作互不依赖） ---\n\nasync function connectPage(statePath, index) {\n  const st = readState(statePath);\n  if (!pidAlive(st.pid)) fail(`浏览器实例未运行（pid=${st.pid} 不在），请先 launch`);\n  const list = await httpJson(`http://127.0.0.1:${st.port}/json/list`);\n  let pages = (list || []).filter((t) => t.type === \"page\");\n  if (pages.length === 0) {\n    await rpc(st.wsUrl, \"Target.createTarget\", { url: \"about:blank\" }, 5000);\n    const list2 = await httpJson(`http://127.0.0.1:${st.port}/json/list`);\n    pages = (list2 || []).filter((t) => t.type === \"page\");\n  }\n  const idx = index === undefined ? 0 : index;\n  const page = pages[idx];\n  if (!page) fail(`无页面 target（共 ${pages.length} 个，index=${idx}）`);\n  await rpc(page.webSocketDebuggerUrl, \"Page.enable\", {});\n  await rpc(page.webSocketDebuggerUrl, \"Runtime.enable\", {});\n  return { st, page };\n}\n\nasync function evalRaw(wsUrl, expression) {\n  const res = await rpc(wsUrl, \"Runtime.evaluate\", {\n    expression,\n    returnByValue: true,\n    awaitPromise: true,\n    userGesture: true,\n  });\n  if (res.exceptionDetails) {\n    throw new Error(\n      `页面执行异常: ${res.exceptionDetails.exception?.description || res.exceptionDetails.text}`,\n    );\n  }\n  return res.result.value;\n}\n\nasync function navigateIfGiven(wsUrl, url, timeoutMs = 15000) {\n  if (!url) return;\n  await rpc(wsUrl, \"Page.navigate\", { url });\n  await poll(\n    async () => (await evalRaw(wsUrl, \"document.readyState\")) === \"complete\",\n    timeoutMs,\n    200,\n  );\n}\n\n/**\n * 解析导航目标：`--url state` 取 state 里的带令牌 URL（GUI 带鉴权，裸端口只会得到\n * 401 文本页），其余原样。state 缺字段时给出可操作错误，而不是静默导航到一张空页。\n * @returns 目标 URL；未给 `--url` 时 null（不导航）。\n */\nfunction resolveTargetUrl(flags, st) {\n  const raw = flag(flags, \"url\", null);\n  if (raw === null || raw !== \"state\") return raw;\n  const url = st?.dshWebUrl;\n  if (!url) {\n    fail(\n      \"--url state 需要 state 文件里存在 dshWebUrl（由 verify-isolated.mjs 写入）；手动拉起的 dsh web 请直接传带令牌的完整 URL\",\n    );\n  }\n  return url;\n}\n\n/**\n * 导航后一次性收尾：跳过首启弹窗 + 鉴权误用诊断。\n *\n * 弹窗由 React 在页面加载后异步挂载（实测晚于 readyState=complete，且时机会在\n * 数百毫秒内波动），故按窗口轮询而不是探一次就下结论——漏检的代价不是「少一次\n * 提示」，而是后续点击落在 inert 根上静默失效、验证结论假绿。等待窗口默认为\n * OVERLAY_WAIT_MS，`--overlay-wait 0` 可退回单次探测（快，但可能漏检）。\n *\n * 两级弹窗（内测声明 → API Key）会无缝衔接：前一个卸载与后一个置位 inert 可能\n * 落在同一帧，故**不能**用「等 inert 解除」判断弹窗已清空（必然超时误报），而是\n * 直接推进到下一轮窗口轮询——没有下一个弹窗时，该轮窗口自然以「无弹窗」收尾。\n *\n * 识别不到跳过按钮时**不点**：弹窗内可能并列「保存并继续」这类有副作用的按钮，\n * 点错会把验证流程变成一次误操作；此时只上报 blocked 交调用方处置。\n */\nasync function settleOverlays(wsUrl, flags) {\n  const result = { dismissed: [], authRequired: false, blocked: null };\n  const auto = !flags.has(\"no-auto-dismiss\");\n  const waitMs = Math.max(0, Number(flag(flags, \"overlay-wait\", String(OVERLAY_WAIT_MS))) || 0);\n  const expr = buildOverlayProbeExpression({ click: auto });\n  for (let round = 0; round < MAX_OVERLAY_ROUNDS; round++) {\n    // 上一轮点过的弹窗需要一点时间卸载，否则本轮窗口会重复命中同一按钮\n    if (round > 0) await sleep(250);\n    let probe = null;\n    let seen = false;\n    const deadline = Date.now() + waitMs;\n    for (;;) {\n      try {\n        probe = await evalRaw(wsUrl, expr);\n      } catch {\n        return result;\n      }\n      if (!probe) return result;\n      if (probe.authRequired) result.authRequired = true;\n      if (probe.blocked) {\n        seen = true;\n        break;\n      }\n      if (Date.now() >= deadline) break;\n      await sleep(150);\n    }\n    if (!seen) return result;\n    if (!probe.dismissed) {\n      result.blocked = { reason: probe.reason, buttons: probe.buttons ?? [] };\n      return result;\n    }\n    result.dismissed.push(probe.clicked);\n  }\n  return result;\n}\n\n/**\n * 导航 + 导航后收尾，导航命令的统一入口。\n * @returns `{ url, overlay }`；未给 `--url` 时 url 与 overlay 均为 null（保持\n * 「省略即不导航」语义——自动导航会抹掉上一条命令的页面状态）。\n */\nasync function goto(wsUrl, flags, st) {\n  const url = resolveTargetUrl(flags, st);\n  if (url === null) return { url: null, overlay: null };\n  await navigateIfGiven(wsUrl, url);\n  const overlay = await settleOverlays(wsUrl, flags);\n  reportOverlay(overlay);\n  return { url, overlay };\n}\n\n/** 把导航后的异常状态报成可操作警告（stderr，不污染 stdout 的 JSON 契约）。 */\nfunction reportOverlay(overlay) {\n  if (!overlay) return;\n  if (overlay.authRequired) {\n    process.stderr.write(\n      \"警告: 页面返回 dsh web 鉴权拒绝（缺访问令牌）——用 --url state 取 state 里的带令牌 URL；裸端口只会得到 401 文本页\\n\",\n    );\n  }\n  if (overlay.blocked) {\n    const detail = overlay.blocked.buttons.length ? `: ${overlay.blocked.buttons.join(\" / \")}` : \"\";\n    process.stderr.write(\n      `警告: 首启弹窗未跳过（${overlay.blocked.reason}${detail}）——应用根仍为 inert，随后点击不会生效\\n`,\n    );\n  }\n}\n\n/** 输出附加字段：只在真的发生时出现，未命中的命令输出契约不变。 */\nfunction overlayFields(overlay) {\n  if (!overlay) return {};\n  const f = {};\n  if (overlay.dismissed.length) f.dismissed = overlay.dismissed;\n  if (overlay.authRequired) f.authRequired = true;\n  if (overlay.blocked) f.onboardingBlocked = overlay.blocked;\n  return f;\n}\n\nfunction selExpr(selector, extra) {\n  return `(() => {\n    const el = document.querySelector(${JSON.stringify(selector)});\n    if (!el) return { found: false };\n    ${extra || \"return { found: true };\"}\n  })()`;\n}\n\nasync function waitSelector(wsUrl, selector, timeoutMs) {\n  // selExpr 未命中返回 { found:false }（对象恒 truthy），poll 必须显式判 found===true，\n  // 否则等待会立即「成功」（假绿）\n  const found = await poll(\n    async () => {\n      try {\n        return (await evalRaw(wsUrl, selExpr(selector))).found === true;\n      } catch {\n        return false;\n      }\n    },\n    timeoutMs,\n    200,\n  );\n  if (!found) throw new Error(`等待选择器超时（${timeoutMs}ms）: ${selector}`);\n}\n\n// --- 设备模拟（视口）---\n\nasync function readViewport(ws) {\n  const r = await rpcRaw(ws, \"Runtime.evaluate\", {\n    expression: \"JSON.stringify({ width: innerWidth, height: innerHeight, dpr: devicePixelRatio })\",\n    returnByValue: true,\n  });\n  return JSON.parse(r.result.value);\n}\n\n/**\n * 在设备模拟条件下执行页面操作；`run` 收到 `{ st, page }`（state 与页面 target）。\n * `--state` / `--index` 与设备 flag 一样由本函数统一取参，页面命令不再各自重复。\n *\n * set / clear 必须走同一条长连接：CDP 的 Emulation 状态按 session 归属，跨连接清除\n * 会静默失效并把尺寸残留给后续命令（依据见 lib/emulation.mjs 头部）。无设备 flag\n * 时不建连接，保持零开销。\n */\nasync function withPageEmulation(flags, run) {\n  // 先解析再连浏览器：参数错误应优先于环境错误报出。\n  const parsed = parseEmulationFlags((name) => flags.get(name));\n  const statePath = flag(flags, \"state\", \"browser.state\");\n  const { st, page } = await connectPage(statePath, Number(flag(flags, \"index\", \"0\")));\n  if (!parsed.active) return run({ st, page });\n  const emuWs = await openRawWs(page.webSocketDebuggerUrl, () => {});\n  let baseline = null;\n  try {\n    baseline = await readViewport(emuWs);\n    await rpcRaw(emuWs, \"Emulation.setDeviceMetricsOverride\", buildDeviceMetrics(parsed, baseline));\n    return await run({ st, page });\n  } finally {\n    // 清理必须可自证：残留会静默污染后续命令，而跨连接 clear 本就不生效，\n    // 故在设置它的这条连接上清除并回读核对；失败只警告不改变命令成败语义。\n    try {\n      await rpcRaw(emuWs, \"Emulation.clearDeviceMetricsOverride\", {});\n      const restored = await readViewport(emuWs);\n      const drifted =\n        baseline &&\n        (restored.width !== baseline.width ||\n          restored.height !== baseline.height ||\n          restored.dpr !== baseline.dpr);\n      if (drifted) {\n        process.stderr.write(\n          `警告: 设备模拟清理后视口未复原（${restored.width}x${restored.height}@${restored.dpr}，期望 ${baseline.width}x${baseline.height}@${baseline.dpr}）——后续命令可能受残留影响，必要时 quit 重建实例\\n`,\n        );\n      }\n    } catch (e) {\n      process.stderr.write(\n        `警告: 设备模拟清理失败（${e.message}）——视口状态可能残留，必要时 quit 重建实例\\n`,\n      );\n    }\n    try {\n      emuWs.close();\n    } catch {}\n  }\n}\n\nasync function cmdSnapshot(flags) {\n  const selector = flag(flags, \"selector\", null);\n  await withPageEmulation(flags, async ({ st, page }) => {\n    const nav = await goto(page.webSocketDebuggerUrl, flags, st);\n    const title = await evalRaw(page.webSocketDebuggerUrl, \"document.title\");\n    const readyState = await evalRaw(page.webSocketDebuggerUrl, \"document.readyState\");\n    const pageUrl = await evalRaw(page.webSocketDebuggerUrl, \"location.href\");\n    let bodyText = null;\n    let element = null;\n    if (selector) {\n      element = await evalRaw(\n        page.webSocketDebuggerUrl,\n        selExpr(\n          selector,\n          `\n        const r = el.getBoundingClientRect();\n        return { found: true, tag: el.tagName, text: (el.innerText || el.textContent || \"\").slice(0, 2000), rect: { x: r.x, y: r.y, width: r.width, height: r.height } };`,\n        ),\n      );\n    } else {\n      bodyText =\n        (await evalRaw(\n          page.webSocketDebuggerUrl,\n          \"document.body ? document.body.innerText.slice(0, 2000) : ''\",\n        )) || \"\";\n    }\n    const pages = ((await httpJson(`http://127.0.0.1:${st.port}/json/list`)) || []).filter(\n      (t) => t.type === \"page\",\n    );\n    out(flags, {\n      ok: true,\n      title,\n      url: redactToken(pageUrl),\n      readyState,\n      tabCount: pages.length,\n      bodyText,\n      element,\n      ...overlayFields(nav.overlay),\n    });\n  });\n}\n\nasync function cmdClick(flags) {\n  const selector = flag(flags, \"selector\", null);\n  const timeoutMs = Number(flag(flags, \"timeout\", \"10000\"));\n  if (!selector) fail(\"click 需要 --selector\");\n  await withPageEmulation(flags, async ({ st, page }) => {\n    const nav = await goto(page.webSocketDebuggerUrl, flags, st);\n    await waitSelector(page.webSocketDebuggerUrl, selector, timeoutMs);\n    const clicked = await evalRaw(\n      page.webSocketDebuggerUrl,\n      selExpr(\n        selector,\n        `\n      el.scrollIntoView({ block: \"center\" });\n      el.click();\n      return { found: true, clicked: true, tag: el.tagName };`,\n      ),\n    );\n    out(flags, {\n      ok: true,\n      selector,\n      clicked,\n      url: nav.url ? redactToken(nav.url) : undefined,\n      ...overlayFields(nav.overlay),\n    });\n  });\n}\n\nasync function cmdEval(flags) {\n  const expression = flag(flags, \"expression\", null);\n  if (!expression) fail(\"eval 需要 --expression\");\n  await withPageEmulation(flags, async ({ page }) => {\n    const value = await evalRaw(page.webSocketDebuggerUrl, expression);\n    out(flags, { ok: true, value });\n  });\n}\n\nasync function cmdFill(flags) {\n  const selector = flag(flags, \"selector\", null);\n  const value = flag(flags, \"value\", \"\");\n  const timeoutMs = Number(flag(flags, \"timeout\", \"10000\"));\n  if (!selector) fail(\"fill 需要 --selector\");\n  await withPageEmulation(flags, async ({ page }) => {\n    await waitSelector(page.webSocketDebuggerUrl, selector, timeoutMs);\n    const filled = await evalRaw(\n      page.webSocketDebuggerUrl,\n      `(() => {\n      const el = document.querySelector(${JSON.stringify(selector)});\n      if (!el) return { found: false };\n      const tag = el.tagName.toLowerCase();\n      if (tag === \"select\") {\n        el.value = ${JSON.stringify(value)};\n        el.dispatchEvent(new Event(\"change\", { bubbles: true }));\n      } else {\n        el.value = ${JSON.stringify(value)};\n        el.dispatchEvent(new Event(\"input\", { bubbles: true }));\n        el.dispatchEvent(new Event(\"change\", { bubbles: true }));\n      }\n      return { found: true, tag, value: el.value };\n    })()`,\n    );\n    out(flags, { ok: true, selector, value, filled });\n  });\n}\n\nasync function cmdWait(flags) {\n  const selector = flag(flags, \"selector\", null);\n  const timeoutMs = Number(flag(flags, \"timeout\", \"10000\"));\n  if (!selector) fail(\"wait 需要 --selector\");\n  await withPageEmulation(flags, async ({ st, page }) => {\n    const started = Date.now();\n    const nav = await goto(page.webSocketDebuggerUrl, flags, st);\n    await waitSelector(page.webSocketDebuggerUrl, selector, timeoutMs);\n    out(flags, {\n      ok: true,\n      selector,\n      waitedMs: Date.now() - started,\n      ...overlayFields(nav.overlay),\n    });\n  });\n}\n\nasync function cmdScreenshot(flags) {\n  const selector = flag(flags, \"selector\", null);\n  const outPath = flag(flags, \"path\", `screenshot-${Date.now()}.png`);\n  await withPageEmulation(flags, async ({ st, page }) => {\n    const nav = await goto(page.webSocketDebuggerUrl, flags, st);\n    let clip = undefined;\n    if (selector) {\n      await waitSelector(page.webSocketDebuggerUrl, selector, 10000);\n      clip = await evalRaw(\n        page.webSocketDebuggerUrl,\n        selExpr(\n          selector,\n          `\n        const r = el.getBoundingClientRect();\n        // getBoundingClientRect 是 viewport 坐标；captureBeyondViewport 下 CDP 按文档\n        // 坐标解释 clip，须加 scrollX/scrollY 转换，否则页面滚动后截空白\n        return { found: true, x: r.x + window.scrollX, y: r.y + window.scrollY, width: r.width, height: r.height, dpr: window.devicePixelRatio || 1 };`,\n        ),\n      );\n      if (!clip || !clip.found) throw new Error(`截图元素未找到: ${selector}`);\n      clip = { x: clip.x, y: clip.y, width: clip.width, height: clip.height, scale: clip.dpr };\n    }\n    const shot = await rpc(page.webSocketDebuggerUrl, \"Page.captureScreens