   await rpcRaw(ws, \"Runtime.enable\", {});\n    await rpcRaw(ws, \"Log.enable\", {});\n    let overlay = null;\n    try {\n      // console 无 --url 时重载当前页（也算一次导航），故两条分支都等就绪后再收尾：\n      // 未就绪时探针读不到弹窗，会错过 inert 这一最关键的事实。\n      const readyExpr = \"document.readyState\";\n      const target = resolveTargetUrl(flags, st);\n      if (target) await rpcRaw(ws, \"Page.navigate\", { url: target });\n      else await rpcRaw(ws, \"Page.reload\", {});\n      await poll(\n        async () => {\n          try {\n            return (\n              (await rpcRaw(ws, \"Runtime.evaluate\", { expression: readyExpr, returnByValue: true }))\n                .result.value === \"complete\"\n            );\n          } catch {\n            return false;\n          }\n        },\n        15000,\n        200,\n      );\n      overlay = await settleOverlays(page.webSocketDebuggerUrl, flags);\n      reportOverlay(overlay);\n    } catch {}\n    await sleep(waitMs);\n    ws.close();\n    out(flags, { ok: true, messages, capturedMs: waitMs, ...overlayFields(overlay) });\n  });\n}\n\n// console 专用：原始 WebSocket 会话（长连接收事件）\nfunction openRawWs(wsUrl, onMessage) {\n  return new Promise((resolve, reject) => {\n    if (typeof WebSocket !== \"function\") {\n      reject(new Error(\"当前 Node 无全局 WebSocket（需 Node >= 22），请升级 Node\"));\n      return;\n    }\n    const ws = new WebSocket(wsUrl);\n    ws.onopen = () => resolve(ws);\n    ws.onerror = () => reject(new Error(`WebSocket 连接失败: ${wsUrl}`));\n    ws.onmessage = onMessage;\n  });\n}\n\nfunction rpcRaw(ws, method, params = {}) {\n  return new Promise((resolve, reject) => {\n    const id = ++rpcRaw.nextId;\n    const timer = setTimeout(() => reject(new Error(`CDP ${method} 超时`)), 15000);\n    const onMsg = (ev) => {\n      let msg;\n      try {\n        msg = JSON.parse(String(ev.data));\n      } catch {\n        return;\n      }\n      if (msg.id === id) {\n        clearTimeout(timer);\n        ws.removeEventListener(\"message\", onMsg);\n        if