wport meta 时 innerWidth 不再等于设定宽度）；触控/真机差异见 references/viewport-geometry.md 能力边界。\n内核探测：DSH_VERIFY_CHROME env > ms-playwright 缓存 > PATH > 平台常见路径，全缺 fail-fast。\n环境要求：Node >= 22（页面操作依赖内置全局 WebSocket）；Chromium 系内核。\n详情见本文件头部注释。`;\n\nconst USAGE = `${USAGE_HEAD}\\n${USAGE_COMMANDS}\\n\\n${USAGE_COMMON}`;\n\nfunction printHelp(cmd) {\n  if (!cmd) {\n    process.stdout.write(USAGE + \"\\n\");\n    return;\n  }\n  const lines = USAGE_COMMANDS.split(\"\\n\").filter((l) => l.includes(cmd));\n  process.stdout.write([USAGE_HEAD, ...lines, \"\", USAGE_COMMON].join(\"\\n\") + \"\\n\");\n}\n\nasync function main() {\n  const argv = process.argv.slice(2);\n  if (argv.length === 0) {\n    process.stdout.write(USAGE + \"\\n\");\n    process.exit(2);\n  }\n  const first = argv[0];\n  if (first === \"--help\" || first === \"-h\" || first === \"help\") {\n    printHelp(argv[1]);\n    process.exit(0);\n  }\n  const { flags } = parseArgs(argv.slice(1));\n  if (flags.has(\"help\")) {\n    printHelp(first);\n    process.exit(0);\n  }\n  const pretty = flags.has(\"pretty\");\n  try {\n    switch (first) {\n      case \"launch\":\n        await cmdLaunch(flags);\n        break;\n      case \"quit\":\n        await cmdQuit(flags);\n        break;\n      case \"snapshot\":\n        await cmdSnapshot(flags);\n        break;\n      case \"click\":\n        await cmdClick(flags);\n        break;\n      case \"eval\":\n        await cmdEval(flags);\n        break;\n      case \"fill\":\n        await cmdFill(flags);\n        break;\n      case \"wait\":\n        await cmdWait(flags);\n        break;\n      case \"screenshot\":\n        await cmdScreenshot(flags);\n        break;\n      case \"console\":\n        await cmdConsole(flags);\n        break;\n      default:\n        jsonOut({ ok: false, error: `未知命令: ${first}` });\n        process.exit(2);\n    }\n    // 成功路径显式退出：launch 等命令持有子进程管道句柄，不显式退出会阻塞事件循环\n    process.exit(0);\n  } catch (e) {\n    jsonOut({ ok: false, error: e.message });\n    pr